async function getCloudflareBots() {
  const cloudflareToken = getInput("cloudflare-api-token", { required: true });
  const botCategories = new Set(
    getMultilineInput("cloudflare-categories", {
      required: true
    })
  );
  const client = new cloudflare_default({ apiToken: cloudflareToken });
  const response = await client.radar.verifiedBots.top.bots({
    dateRange: ["30d"],
    // This limit may need to be increased at some point.
    // For some reason it's crashing with higher limits. This appears to be a hidden limit with no guidance.
    limit: 300
  }).catch((err) => {
    if (err instanceof APIError) {
      error(JSON.stringify(err.errors));
    }
    throw new Error("Error requesting top bots from Cloudflare");
  });
  const names = response.top_0.filter((bot) => botCategories.has(bot.botCategory)).map((bot) => bot.botName).sort();
  startGroup(`User agents from Cloudflare (${names.length})`);
  info(names.join("\n"));
  endGroup();
  return new Set(names);
}

// src/dark-visitors.ts
async function getDarkVisitorsUserAgents() {
  const darkVisitorsToken = getInput("dark-visitors-api-token", {
    required: true
  });
  const botCategories = getMultilineInput("dark-visitors-categories", {
    required: true
  });
  const baseRobotsTxt = await fetch(
    "https://api.darkvisitors.com/robots-txts",
    {
      method: "POST",
      headers: new Headers({
        Authorization: `Bearer ${darkVisitorsToken}`,
        "Content-Type": "application/json"
      }),
      body: JSON.stringify({
        agent_types: botCategories,
        disallow: "/"
      })
    }
  ).then(async (response) => response.text()).catch((err) => {
    if (err instanceof Error) {
      error(err);
    }
    throw new Error("Error requesting robots.txt from Dark Visitors");
  });
  const userAgents = Array.from(baseRobotsTxt.matchAll(/^User-agent: (.*)$/gm)).map((match) => match[1]).sort();
  startGroup(`User agents from Dark Visitors (${userAgents.length})`);
  info(userAgents.join("\n"));
  endGroup();
  return new Set(userAgents);
}

